// Type-checks index.d.ts with the TypeScript compiler (`npm run typecheck`,
// run by `make test-litsea-nodejs`). Nothing here runs: the file only has to
// compile. index.d.ts is generated by napi-rs, so a `ts_return_type` that
// names a type the generated file does not declare compiles in Rust and only
// fails here (#286).

import {
  CancelToken,
  PerceptronTrainer,
  Trainer,
  TwoStageTrainer,
  type BinaryMetrics,
  type MulticlassMetrics,
  type TwoStageMetrics,
} from '../index.js'

/**
 * Receives each `train()` result as the metric type the docs name.
 *
 * @param trainer - An AdaBoost trainer.
 * @param perceptron - An Averaged Perceptron trainer.
 * @param twoStage - A two-stage trainer.
 * @returns The three sets of metrics.
 */
export async function trainAll(
  trainer: Trainer,
  perceptron: PerceptronTrainer,
  twoStage: TwoStageTrainer,
): Promise<[BinaryMetrics, MulticlassMetrics, TwoStageMetrics]> {
  const cancel = new CancelToken()
  const binary: BinaryMetrics = await trainer.train('binary.model', cancel)
  const multiclass: MulticlassMetrics = await perceptron.train('perceptron.model')
  const stages: TwoStageMetrics = await twoStage.train('two_stage.model')
  const stage1: MulticlassMetrics = stages.stage1
  const recall: number = binary.recall + multiclass.macroRecall + stage1.macroRecall
  void recall
  return [binary, multiclass, stages]
}
